#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/android/tasks/setup-deps-android.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install the Android SDK packages of the build: platform-tools, the platform, the emulator and its system image"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="accepted for the setup contract; the SDK packages have no lockfile, so an upgrade installs the same packages"

import os
import re
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

ENV_FILE = ".config/mise/conf.d/zz-repo/mise.<env>.toml"
ABIS = ("/arm64-v8a", "/x86_64", "/x86", "/armeabi-v7a")
SPACE = rb"[ \t\r\f\v]"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def build_files():
  """The files that the detects read, as (level_files, kts_files).

  The detects read only the files that git tracks or does not ignore, so an
  ignored folder (.worktrees/, .claude/worktrees/, node_modules) is not read.
  The pathspecs give only the files that the detects read. The build/ and
  .gradle/ folders are not read. level_files has the order of the level
  detect: the build.gradle.kts and *.gradle files (Kotlin and Groovy DSL),
  then each file in build-logic/, then gradle/libs.versions.toml. Each part is
  sorted.
  """
  result = subprocess.run(
    [
      "git",
      "ls-files",
      "-z",
      "--cached",
      "--others",
      "--exclude-standard",
      "--",
      "*.gradle",
      "*.gradle.kts",
      "build-logic/*",
      "gradle/libs.versions.toml",
    ],
    check=False,
    stdout=subprocess.PIPE,
    stderr=subprocess.DEVNULL,
  )
  build, logic, catalog, kts = [], [], [], []
  for name in sorted(n for n in result.stdout.split(b"\0") if n):
    file = os.fsdecode(name)
    if not os.path.isfile(file):
      continue
    if file.startswith(("build/", ".gradle/")) or "/build/" in file or "/.gradle/" in file:
      continue
    if file.startswith("build-logic/"):
      logic.append(file)
    elif file == "gradle/libs.versions.toml":
      catalog.append(file)
    elif file == "build.gradle.kts" or file.endswith(("/build.gradle.kts", ".gradle")):
      build.append(file)
    elif file.endswith(".gradle.kts"):
      kts.append(file)
  return build + logic + catalog, kts


def read(file):
  """The bytes of file, or None when it cannot be read."""
  try:
    with open(file, "rb") as data:
      return data.read()
  except OSError:
    return None


def detect_level(key, level_files):
  """(level, file) for the first hit of key (compileSdk or targetSdk) in
  level_files. Only a literal level counts, for example `compileSdk = 36`,
  `compileSdkVersion(34)`, `compileSdk 35` or `compileSdkVersion 35` (Groovy
  DSL), or `compileSdk = "36"` in the version catalog. None without a hit. A
  binary file, for example a jar in build-logic/, is not read.
  """
  pattern = re.compile(
    rb"(^|[^A-Za-z])" + key.encode() + rb"(Version)?" + SPACE + rb"*[=(]?" + SPACE + rb'*"?[0-9]+(\.[0-9]+)?'
  )
  for file in level_files:
    data = read(file)
    if data is None or b"\0" in data:
      continue
    for line in data.split(b"\n"):
      hit = pattern.search(line)
      if hit:
        level = re.search(rb"[0-9]+(\.[0-9]+)?$", hit.group(0)).group(0)
        return level.decode(), file
  return None


def normalize_level(name, level):
  """A level must be a number with an optional minor. The repository from API
  37 names each level with its minor, so a bare level of 37 or more becomes
  <level>.0. Returns the level, or stops the task with code 1.
  """
  if not re.fullmatch(r"[0-9]+(\.[0-9]+)?", level):
    helpers.print_error(f"{name} '{level}' is not a level: it must match ^[0-9]+(\\.[0-9]+)?$")
    sys.exit(1)
  if re.fullmatch(r"[0-9]+", level) and int(level) >= 37:
    level = f"{level}.0"
  return level


def main():
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # Shipped with the android tool. It acts on the Gradle build at the root
  # only: the android/ folder of a Flutter app is for setup:deps:20-flutter.
  # Without an executable ./gradlew and the Android Gradle plugin, the task
  # does not apply and prints nothing.
  if not os.access("gradlew", os.X_OK):
    sys.exit(0)

  level_files, kts_files = build_files()
  # The Android Gradle plugin is in the files of the level detect, or in an
  # other *.gradle.kts file, for example settings.gradle.kts.
  agp_files = level_files + kts_files
  if not agp_files:
    sys.exit(0)
  agp = re.compile(rb"com\.android\.(application|library)")
  if not any(agp.search(read(file) or b"") for file in agp_files):
    sys.exit(0)

  helpers.print_header("Installing the Android SDK packages ...")

  # The android-sdk mise tool sets ANDROID_HOME, the SDK root of the android
  # CLI. The installed check reads the packages there.
  android_home = os.environ.get("ANDROID_HOME", "")
  if not android_home:
    helpers.print_error("ANDROID_HOME is not set, so the task cannot find the SDK")
    helpers.print_info("The android-sdk mise tool sets it; do not unset it in the mise config")
    sys.exit(1)

  helpers.print_subheader("Detecting the SDK levels ...")
  if os.environ.get("COMPILE_SDK", ""):
    compile_raw = os.environ["COMPILE_SDK"]
    helpers.print_info(f"compileSdk {compile_raw}, from the env value COMPILE_SDK")
  else:
    hit = detect_level("compileSdk", level_files)
    if not hit:
      helpers.print_error(
        "No compileSdk level found in the build.gradle.kts and *.gradle files, build-logic/ or"
        " gradle/libs.versions.toml"
      )
      helpers.print_info(f"Set COMPILE_SDK in the [env] of {ENV_FILE}")
      sys.exit(1)
    compile_raw = hit[0]
    helpers.print_info(f"compileSdk {compile_raw}, from {hit[1]}")
  compile_level = normalize_level("COMPILE_SDK", compile_raw)

  abi = "arm64-v8a" if os.uname().machine in ("arm64", "aarch64") else "x86_64"

  # The android CLI names a package with "/", where sdkmanager uses ";". An id
  # in either form is accepted. The task never replaces an explicit image.
  explicit = False
  if os.environ.get("EMULATOR_IMAGE", ""):
    explicit = True
    image = os.environ["EMULATOR_IMAGE"].replace(";", "/")
    helpers.print_info(f"Emulator image {image}, from the env value EMULATOR_IMAGE")
  else:
    hit = detect_level("targetSdk", level_files)
    if not hit:
      helpers.print_error(
        "No targetSdk level found in the build.gradle.kts and *.gradle files, build-logic/ or gradle/libs.versions.toml"
      )
      helpers.print_info(f"Set EMULATOR_IMAGE in the [env] of {ENV_FILE}")
      sys.exit(1)
    target_raw = hit[0]
    helpers.print_info(f"targetSdk {target_raw}, from {hit[1]}")
    target_level = normalize_level("targetSdk", target_raw)
    image = f"system-images/android-{target_level}/google_apis"
  # The image id names the ABI of this host, unless it already ends with one.
  if not image.endswith(ABIS):
    image = f"{image}/{abi}"
  helpers.print_info(f"ABI {abi}")

  platform = f"platforms/android-{compile_level}"

  # An installed package has <id>/package.xml in the SDK, so this check needs
  # no network. When every package is there, the task lists and installs
  # nothing.
  def installed(package):
    return os.path.isfile(f"{android_home}/{package}/package.xml")

  missing = [package for package in ("platform-tools", platform, "emulator") if not installed(package)]

  # From android-37.1, only the _ps16k variant (16 KB pages) of an image
  # exists. An installed variant counts as the derived image, so the task needs
  # no network list.
  head, sep, tail = image.rpartition("/")
  if not sep:
    head = tail = image
  variant = f"{head}_ps16k/{tail}"
  if not explicit and not installed(image) and installed(variant):
    helpers.print_info(f"{image} is not installed; using the installed {variant}")
    image = variant

  # The list has the installed packages, then the available ones; the id is
  # the first column. The emulator image is checked against it, unless the
  # image is installed.
  if not installed(image):
    helpers.print_subheader("Listing the SDK packages ...")
    result = helpers.tool("android", "sdk", "list", "--all", stdout=subprocess.PIPE)
    packages = set()
    if result.returncode == 0:
      for line in os.fsdecode(result.stdout).splitlines():
        fields = line.split()
        if fields:
          packages.add(fields[0])
    if not packages:
      helpers.print_error("The android CLI listed no SDK packages")
      sys.exit(1)

    # The variant replaces a missing derived image, and the task names the id
    # it used.
    if image not in packages:
      if explicit:
        helpers.print_error(f"The SDK has no package {image}")
        helpers.print_info(f"Change EMULATOR_IMAGE in the [env] of {ENV_FILE}")
        sys.exit(1)
      elif variant in packages:
        helpers.print_warn(f"The SDK has no package {image}; using {variant}")
        image = variant
      else:
        helpers.print_error(f"The SDK has neither {image} nor {variant}")
        helpers.print_info(f"Set EMULATOR_IMAGE in the [env] of {ENV_FILE}")
        sys.exit(1)
    if not installed(image):
      missing.append(image)

  if not missing:
    helpers.print_success(f"platform-tools, {platform}, emulator and {image} are installed")
    sys.exit(0)

  # A folder of a package without its package.xml is left from an install that
  # did not complete. The installer then writes to another folder, and the
  # check after the install fails, so the task stops first and names the
  # folder.
  leftover = [package for package in missing if os.path.isdir(f"{android_home}/{package}")]
  if leftover:
    for package in leftover:
      helpers.print_error(f"{android_home}/{package} has no package.xml; an install of it did not complete")
    helpers.print_info("Delete each folder above, then run the task again.")
    sys.exit(1)

  helpers.print_subheader(f"Installing {' '.join(missing)} ...")
  # cmdline-tools 23 has no license prompt: a package install accepts the SDK
  # license and writes licenses/, which Gradle reads before it downloads the
  # build tools and the NDK.
  result = helpers.tool("android", "sdk", "install", *missing)
  if result.returncode != 0:
    sys.exit(exit_code(result.returncode))

  # An unknown id can install nothing, and the install can still exit 0. Each
  # package that the task asked for must have its package.xml now.
  not_installed = [package for package in missing if not installed(package)]
  if not_installed:
    for package in not_installed:
      helpers.print_error(f"The android CLI did not install {package}")
    sys.exit(1)
  helpers.print_success("Android SDK packages installed")


main()
